import{createLogger,logError}from"#internal/logging.js";import{readDurableSession}from"#execution/durable-session-store.js";import{getAgentHandleStore}from"#harness/handles/store.js";import{cancelRun,getWorld}from"#internal/workflow/runtime.js";const log=createLogger(`execution.terminate-child-sessions`);async function terminateChildSessionsStep(e){"use step";let r;try{r=await readDurableSession(e.sessionState)}catch(n){logError(log,`failed to read child sessions for termination`,n,{parentSessionId:e.sessionState.sessionId});return}let i=(getAgentHandleStore(r.state)?.handles??[]).filter(isLocalChildHandle);if(i.length!==0)for(let e of i){if(e.phase===`starting`){log.debug(`skipping starting child without a session id`,{agentId:e.identity.id,kind:e.target.kind,parentSessionId:r.sessionId});continue}try{await cancelRun(await getWorld(),e.address.sessionId,{cancelReason:`Parent session ended`})}catch(n){logError(log,`failed to terminate child session`,n,{agentId:e.identity.id,childSessionId:e.address.sessionId,kind:e.address.kind,parentSessionId:r.sessionId})}}}function isLocalChildHandle(e){let t=e.phase===`starting`?e.target.kind:e.address.kind;return t===`agent/local`||t===`agent/self`}export{terminateChildSessionsStep};